{"code":"from hermes_tools import terminal
cmd = r'''python3 - <<'PY'
import openpyxl, os, re, sys
from openpyxl.utils import get_column_letter
out='/root/output/result.xlsx'
wb=openpyxl.load_workbook(out, data_only=False)
ws=wb['Task']
print('Reopened:', out)
print('Sheet names:', wb.sheetnames)
sample_cells=['H12','L17','H19','L24','H26','L31','H35','L40','H42','H47','H50','L50']
print('Sample formulas:')
for addr in sample_cells:
    print(addr, ws[addr].value)
errors=[]
# Validate all target cells have formulas
for rangestr in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    for row in ws[rangestr]:
        for cell in row:
            v=cell.value
            if not (isinstance(v,str) and v.startswith('=')):
                errors.append(f'{cell.coordinate} not formula: {v!r}')
# Expected exact Step 1 formulas
for r1,r2 in [(12,17),(19,24),(26,31)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            col=get_column_letter(c)
            exp=f'=INDEX(Data!$H$21:$L$38, MATCH($D{r},Data!$D$21:$D$38,0), MATCH({col}$10,Data!$H$4:$L$4,0))'
            if ws.cell(r,c).value != exp:
                errors.append(f'{col}{r} expected {exp}, got {ws.cell(r,c).value}')
# Expected slack formulas
for r in range(35,41):
    off=r-35; fin=12+off; scrap=19+off; cap=26+off
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=({col}{fin} - {col}{scrap}) / {col}{cap} * 100'
        if ws.cell(r,c).value != exp:
            errors.append(f'{col}{r} expected {exp}, got {ws.cell(r,c).value}')
# Expected stats
for c in range(8,13):
    col=get_column_letter(c)
    expected={
        42:f'=MIN({col}35:{col}40)',
        43:f'=MAX({col}35:{col}40)',
        44:f'=MEDIAN({col}35:{col}40)',
        45:f'=AVERAGE({col}35:{col}40)',
        46:f'=PERCENTILE({col}35:{col}40,0.25)',
        47:f'=PERCENTILE({col}35:{col}40,0.75)',
        50:f'=SUMPRODUCT({col}35:{col}40, {col}26:{col}31) / SUM({col}26:{col}31)',
    }
    for r, exp in expected.items():
        if ws.cell(r,c).value != exp:
            errors.append(f'{col}{r} expected {exp}, got {ws.cell(r,c).value}')
# Function name presence in samples/blocks
requirements={
    'H12':['INDEX','MATCH'], 'L17':['INDEX','MATCH'], 'H19':['INDEX','MATCH'], 'L24':['INDEX','MATCH'], 'H26':['INDEX','MATCH'], 'L31':['INDEX','MATCH'],
    'H42':['MIN'], 'H43':['MAX'], 'H44':['MEDIAN'], 'H45':['AVERAGE'], 'H46':['PERCENTILE'], 'H47':['PERCENTILE'], 'H50':['SUMPRODUCT','SUM'], 'L50':['SUMPRODUCT','SUM']
}
for addr, funcs in requirements.items():
    v=ws[addr].value or ''
    for f in funcs:
        if f not in v:
            errors.append(f'{addr} missing {f}: {v}')
# Confirm no accidental PERCENTILE.INC/EXC
for r in [46,47]:
    for c in range(8,13):
        v=ws.cell(r,c).value
        if 'PERCENTILE.INC' in v or 'PERCENTILE.EXC' in v:
            errors.append(f'{ws.cell(r,c).coordinate} uses unsupported percentile variant: {v}')
print('Formula cell count checked:', sum(1 for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50'] for row in ws[rng] for cell in row))
if errors:
    print('VALIDATION FAILED')
    for e in errors[:50]: print('ERROR', e)
    print('error_count', len(errors))
    sys.exit(1)
print('VALIDATION PASSED')
PY'''
